package com.growworld.security;
import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.AuthorityUtils; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtAuthenticationFilter(JwtService jwt){this.jwt=jwt;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException { try {String token=Arrays.stream(Optional.ofNullable(req.getCookies()).orElse(new Cookie[0])).filter(c->"GW_AUTH".equals(c.getName())).map(Cookie::getValue).findFirst().orElse(null); if(token!=null){var auth=new UsernamePasswordAuthenticationToken(jwt.subject(token),null, AuthorityUtils.NO_AUTHORITIES);SecurityContextHolder.getContext().setAuthentication(auth);}}catch(JwtException|IllegalArgumentException ignored){SecurityContextHolder.clearContext();} chain.doFilter(req,res);}}
